```javascript
const fs = require('fs');
const lines = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
const n = parseInt(lines[0], 10);

const total = new Map();
const pendingTime = new Map();
const pending = new Set();

let time = 0;
let hasEvent = false;
let prevWasT = false;

for (let i = 1; i <= n; i++) {
  const line = lines[i].trim();
  if (!line) continue;

  const [type, xs] = line.split(/\s+/);
  const x = parseInt(xs, 10);

  if (type === 'T') {
    time += x;
    prevWasT = true;
  } else {
    if (hasEvent && !prevWasT) {
      time += 1;
    }

    if (!total.has(x)) total.set(x, 0);

    if (type === 'R') {
      pendingTime.set(x, time);
      pending.add(x);
    } else {
      if (pending.has(x)) {
        total.set(x, total.get(x) + time - pendingTime.get(x));
        pending.delete(x);
        pendingTime.delete(x);
      }
    }

    hasEvent = true;
    prevWasT = false;
  }
}

const ids = Array.from(total.keys()).sort((a, b) => a - b);
let out = '';

for (const id of ids) {
  const ans = pending.has(id) ? -1 : total.get(id);
  out += `${id} ${ans}\n`;
}

process.stdout.write(out);
